UPDATE public.dictionary_words SET example_hanzi = '這家連鎖飲料店決定在臺中設立新的分店。', example_pinyin = 'zhè jiā lián suǒ yǐn liào diàn jué dìng zài tái zhōng shè lì xīn de fēn diàn 。', example_vietnamese = 'Chuỗi cửa hàng đồ uống này quyết định thành lập một chi nhánh mới tại Đài Trung.' WHERE id = '357c182d-9e93-458f-807e-f1d396648982';
UPDATE public.dictionary_words SET example_hanzi = '為了方便民眾，臺北市政府在公園裡設置了許多運動器材。', example_pinyin = 'wéi le fāng biàn mín zhòng ， tái běi shì zhèng fǔ zài gōng yuán lǐ shè zhì le xū duō yùn dòng qì cái 。', example_vietnamese = 'Để thuận tiện cho người dân, Chính quyền thành phố Đài Bắc đã lắp đặt nhiều thiết bị tập thể dục trong công viên.' WHERE id = 'b5ce1da8-0274-4d3d-b7ad-395b66b794fd';
UPDATE public.dictionary_words SET example_hanzi = '很多人到臺灣旅遊，喜歡用手機攝影記錄下美景和美食。', example_pinyin = 'hěn duō rén dào tái wān lǚ yóu ， xǐ huān yòng shǒu jī shè yǐng jì lù xià měi jǐng hé měi shí 。', example_vietnamese = 'Nhiều người đến Đài Loan du lịch, thích dùng điện thoại để chụp ảnh ghi lại cảnh đẹp và món ngon.' WHERE id = '74a1df96-02ac-4625-bc13-6d49e88b829a';
UPDATE public.dictionary_words SET example_hanzi = '他決定申請去臺大讀研究所。', example_pinyin = 'tā jué dìng shēn qǐng qù tái dà dú yán jiū suǒ 。', example_vietnamese = 'Anh ấy quyết định đăng ký học cao học tại Đại học Quốc gia Đài Loan.' WHERE id = 'bc86eb22-d502-429d-b831-ef7bd2bc5edc';
UPDATE public.dictionary_words SET example_hanzi = '老師請小朋友伸出雙手，排隊洗手。', example_pinyin = 'lǎo shī qǐng xiǎo péng yǒu shēn chū shuāng shǒu ， pái duì xǐ shǒu 。', example_vietnamese = 'Cô giáo yêu cầu các bé duỗi hai tay ra, xếp hàng rửa tay.' WHERE id = '4fc72606-417f-40d8-b012-60a49983730e';
UPDATE public.dictionary_words SET example_hanzi = '在夜市裡，小孩忍不住伸手想摸攤位上的小吃。', example_pinyin = 'zài yè shì lǐ ， xiǎo hái rěn bú zhù shēn shǒu xiǎng mō tān wèi shàng de xiǎo chī 。', example_vietnamese = 'Trong chợ đêm, đứa trẻ không nhịn được vươn tay muốn chạm vào món ăn vặt trên quầy hàng.' WHERE id = 'a7dfa45f-ec76-419d-96e0-5c55a22958b7';
UPDATE public.dictionary_words SET example_hanzi = '許多臺灣的年輕人注重飲食和運動來保持身材。', example_pinyin = 'xū duō tái wān de nián qīng rén zhù zhòng yǐn shí hé yùn dòng lái bǎo chí shēn cái 。', example_vietnamese = 'Nhiều người trẻ Đài Loan chú trọng ăn uống và tập thể dục để giữ dáng.' WHERE id = '5d4c95da-041c-48f4-aa29-5fbe15c490fc';
UPDATE public.dictionary_words SET example_hanzi = '飯店櫃檯請客人出示身分以辦理入住。', example_pinyin = 'fàn diàn guì tái qǐng kè rén chū shì shēn fèn yǐ bàn lǐ rù zhù 。', example_vietnamese = 'Quầy lễ tân khách sạn yêu cầu khách xuất trình giấy tờ tùy thân để làm thủ tục nhận phòng.' WHERE id = '50c6284d-8387-4a59-acea-229bb0365556';
UPDATE public.dictionary_words SET example_hanzi = '去便利商店買酒或菸需要出示身分證。', example_pinyin = 'qù biàn lì shāng diàn mǎi jiǔ huò yān xū yào chū shì shēn fèn zhèng 。', example_vietnamese = 'Khi mua rượu hoặc thuốc lá ở cửa hàng tiện lợi cần xuất trình chứng minh nhân dân.' WHERE id = 'a8a10b32-dd3a-43a2-be39-f4bf67edfc4a';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的熱情和美食給我留下了深刻的印象。', example_pinyin = 'tái wān de rè qíng hé měi shí gěi wǒ liú xià le shēn kè de yìn xiàng 。', example_vietnamese = 'Lòng hiếu khách và ẩm thực ngon của Đài Loan đã để lại ấn tượng sâu sắc trong tôi.' WHERE id = 'ad932dff-6400-4a7f-bac0-77bbbf978cbb';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的海灘常常有深淺不一的海流，下水要特別注意安全。', example_pinyin = 'tái wān de hǎi tān cháng cháng yǒu shēn qiǎn bù yī de hǎi liú ， xià shuǐ yào tè bié zhù yì ān quán 。', example_vietnamese = 'Các bãi biển ở Đài Loan thường có dòng chảy sâu nông khác nhau, phải đặc biệt chú ý an toàn khi xuống nước.' WHERE id = 'decb20ab-26af-41bc-828c-a24982e5f5c1';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的便利商店即使深夜也燈火通明，非常方便。', example_pinyin = 'tái wān de biàn lì shāng diàn jí shǐ shēn yè yě dēng huǒ tōng míng ， fēi cháng fāng biàn 。', example_vietnamese = 'Các cửa hàng tiện lợi ở Đài Loan dù là đêm khuya cũng sáng đèn, rất tiện lợi.' WHERE id = '636060ff-5be5-4295-b25f-5dd74461a2b4';
UPDATE public.dictionary_words SET example_hanzi = '臺灣人喜歡到廟裡拜神祈福。', example_pinyin = 'tái wān rén xǐ huān dào miào lǐ bài shén qí fú 。', example_vietnamese = 'Người Đài Loan thích đến chùa cúng thần và cầu phúc.' WHERE id = '8c3eb53b-7b20-46d8-a94e-19d500c3be85';
UPDATE public.dictionary_words SET example_hanzi = '臺灣原住民有很多關於天地起源的神話故事。', example_pinyin = 'tái wān yuán zhù mín yǒu hěn duō guān wū tiān dì qǐ yuán de shén huà gù shì 。', example_vietnamese = 'Các dân tộc bản địa Đài Loan có nhiều câu chuyện thần thoại về nguồn gốc trời đất.' WHERE id = '748fc683-9e38-481e-b96f-8dcc0ea269e0';
UPDATE public.dictionary_words SET example_hanzi = '長時間使用手機可能會傷害到手部神經。', example_pinyin = 'cháng shí jiàn shǐ yòng shǒu jī kě néng huì shāng hài dào shǒu bù shén jīng 。', example_vietnamese = 'Sử dụng điện thoại di động trong thời gian dài có thể làm tổn thương dây thần kinh ở tay.' WHERE id = '3cdb055e-8605-4425-a057-c8abc7286384';
UPDATE public.dictionary_words SET example_hanzi = '這個地方有一種神秘的氣氛，讓人很好奇。', example_pinyin = 'zhè gè dì fāng yǒu yì zhǒng shén mì de qì fēn ， ràng rén hěn hào qí 。', example_vietnamese = 'Nơi này có một bầu không khí huyền bí, khiến người ta rất tò mò.' WHERE id = '92bad4e0-47e3-46fd-9f1a-5d90cda37ee9';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的夜市有許多神奇的小吃，每次都能發現新口味。', example_pinyin = 'tái wān de yè shì yǒu xū duō shén qí de xiǎo chī ， měi cì dōu néng fā xiàn xīn kǒu wèi 。', example_vietnamese = 'Chợ đêm Đài Loan có nhiều món ăn vặt thần kỳ, mỗi lần đều có thể khám phá hương vị mới.' WHERE id = '49fc414b-fb30-4276-a58f-5298cec39fcc';
UPDATE public.dictionary_words SET example_hanzi = '小朋友穿著新衣服，走起路來特別神氣。', example_pinyin = 'xiǎo péng yǒu chuān zhù xīn yī fu ， zǒu qǐ lù lái tè bié shén qì 。', example_vietnamese = 'Em bé mặc quần áo mới, đi bộ trông rất oai phong/đắc ý.' WHERE id = '31b7911c-0c5b-481e-8ab6-bc6b5a0c76c4';
UPDATE public.dictionary_words SET example_hanzi = '這座龍山寺對當地居民來說是個很神聖的信仰中心。', example_pinyin = 'zhè zuò lóng shān sì duì dāng dì jū mín lái shuō shì gè hěn shén shèng de xìn yǎng zhōng xīn 。', example_vietnamese = 'Chùa Long Sơn này là một trung tâm tín ngưỡng rất thiêng liêng đối với cư dân địa phương.' WHERE id = '3330c55f-c49b-47ca-9cb1-480af0ee1867';
UPDATE public.dictionary_words SET example_hanzi = '臺灣傳統故事裡，常常會提到八仙過海的神仙。', example_pinyin = 'tái wān chuán tǒng gù shì lǐ ， cháng cháng huì tí dào bā xiān guò hǎi de shén xiān 。', example_vietnamese = 'Trong các câu chuyện truyền thống Đài Loan, thường nhắc đến các vị thần tiên Bát Tiên quá hải.' WHERE id = 'a225bb05-691a-4ca3-9f7c-a5a0949bc4d3';
UPDATE public.dictionary_words SET example_hanzi = '國稅局會審查企業的報稅資料。', example_pinyin = 'guó shuì jú huì shěn chá qǐ yè de bào shuì zī liào 。', example_vietnamese = 'Cục Thuế quốc gia sẽ kiểm tra hồ sơ khai thuế của doanh nghiệp.' WHERE id = 'e9065dba-06d4-4e7d-8b06-002e182d0072';
UPDATE public.dictionary_words SET example_hanzi = '買房是大事，一定要慎重評估地點和價格。', example_pinyin = 'mǎi fáng shì dà shì ， yí dìng yào shèn zhòng píng gū dì diǎn hé jià gé 。', example_vietnamese = 'Mua nhà là chuyện lớn, nhất định phải thận trọng đánh giá địa điểm và giá cả.' WHERE id = '972c858f-22b5-4cd4-88c1-0587e35e9403';
UPDATE public.dictionary_words SET example_hanzi = '太陽從東邊升起。', example_pinyin = 'tài yáng cóng dōng biān shēng qǐ 。', example_vietnamese = 'Mặt trời mọc từ phía đông.' WHERE id = 'a9c987d2-8445-43e0-9c2a-6642c6001e02';
UPDATE public.dictionary_words SET example_hanzi = '夏天到了，臺灣各地的氣溫都會升高。', example_pinyin = 'xià tiān dào le ， tái wān gè dì de qì wēn dōu huì shēng gāo 。', example_vietnamese = 'Mùa hè đến rồi, nhiệt độ khắp Đài Loan sẽ tăng cao.' WHERE id = '9c175c50-78de-4f2c-9717-f6a9e33530fd';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的許多公共建設，如捷運系統，會定期進行維護和升級。', example_pinyin = 'tái wān de xū duō gōng gòng jiàn shè ， rú jié yùn xì tǒng ， huì dìng qī jìn xíng wéi hù hé shēng jí 。', example_vietnamese = 'Nhiều công trình công cộng của Đài Loan, như hệ thống MRT, được bảo trì và nâng cấp định kỳ.' WHERE id = 'd5b9ab22-a449-4d23-b2a2-863cf5021b6d';
UPDATE public.dictionary_words SET example_hanzi = '在臺灣，許多國中生會為了升學而補習。', example_pinyin = 'zài tái wān ， xū duō guó zhōng shēng huì wéi le shēng xué ér bǔ xí 。', example_vietnamese = 'Ở Đài Loan, nhiều học sinh cấp hai sẽ học thêm để thi lên cấp ba/đại học.' WHERE id = 'de0c8e42-dad0-485c-a64d-0156b0e00d4c';
UPDATE public.dictionary_words SET example_hanzi = '她生了一個可愛的女兒。', example_pinyin = 'tā shēng le yí gè kě ài de nǚ ér 。', example_vietnamese = 'Cô ấy sinh một cô con gái đáng yêu.' WHERE id = '526dc651-cf71-41e3-8af3-a897a5667741';
UPDATE public.dictionary_words SET example_hanzi = '臺灣黑熊的生存環境受到人類開發的威脅。', example_pinyin = 'tái wān hēi xióng de shēng cún huán jìng shòu dào rén lèi kāi fā de wēi xié 。', example_vietnamese = 'Môi trường sống của gấu đen Đài Loan bị đe dọa bởi sự phát triển của con người.' WHERE id = '741d8d1b-a78b-4848-81bd-d8fd8f5ac7f5';
UPDATE public.dictionary_words SET example_hanzi = '在臺灣，人們會用生肖來問對方的年齡。', example_pinyin = 'zài tái wān ， rén men huì yòng shēng xiào lái wèn duì fāng de nián líng 。', example_vietnamese = 'Ở Đài Loan, người ta đôi khi dùng con giáp để hỏi tuổi của nhau.' WHERE id = 'cb81c364-117d-45ed-a508-63a08e9a2f2c';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的熱帶水果在夏天快速生長。', example_pinyin = 'tái wān de rè dài shuǐ guǒ zài xià tiān kuài sù shēng cháng 。', example_vietnamese = 'Trái cây nhiệt đới của Đài Loan phát triển nhanh chóng vào mùa hè.' WHERE id = '62a64954-6e12-4776-9f91-577c9cf77fc5';
UPDATE public.dictionary_words SET example_hanzi = '我聽到一聲巨響。', example_pinyin = 'wǒ tīng dào yì shēng jù xiǎng 。', example_vietnamese = 'Tôi nghe thấy một tiếng động lớn.' WHERE id = 'aed29214-eac8-4e77-b381-9b4e2a9d4d7a';
UPDATE public.dictionary_words SET example_hanzi = '小朋友在公園裡玩跳繩，消耗體力。', example_pinyin = 'xiǎo péng yǒu zài gōng yuán lǐ wán tiào shéng ， xiāo hào tǐ lì 。', example_vietnamese = 'Các em nhỏ chơi nhảy dây trong công viên, tiêu hao năng lượng.' WHERE id = '30afe8ff-9032-4192-ad16-e264de0ab6f6';
UPDATE public.dictionary_words SET example_hanzi = '他很會省錢。', example_pinyin = 'tā hěn huì shěng qián 。', example_vietnamese = 'Anh ấy rất giỏi tiết kiệm tiền.' WHERE id = '0ffca375-15af-45a7-a05c-4ad49d4bb1e9';
UPDATE public.dictionary_words SET example_hanzi = '假日去夜市最好搭捷運，省得找停車位。', example_pinyin = 'jiǎ rì qù yè shì zuì hǎo dā jié yùn ， shěng de zhǎo tíng chē wèi 。', example_vietnamese = 'Cuối tuần đi chợ đêm tốt nhất nên đi MRT, để khỏi phải tìm chỗ đậu xe.' WHERE id = 'c3635427-ef0c-4ffa-97df-6b88f89f7dd7';
UPDATE public.dictionary_words SET example_hanzi = '這次籃球比賽，我們隊伍最後以一分險勝。', example_pinyin = 'zhè cì lán qiú bǐ sài ， wǒ men duì wǔ zuì hòu yǐ yì fēn xiǎn shèng 。', example_vietnamese = 'Trong trận đấu bóng rổ lần này, đội chúng ta cuối cùng đã thắng sít sao một điểm.' WHERE id = '88032463-1d54-43fd-9ec2-f5546124d5f9';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的運動員在國際賽事中爭取勝利，為國爭光。', example_pinyin = 'tái wān de yùn dòng yuán zài guó jì sài shì zhōng zhēng qǔ shèng lì ， wéi guó zhēng guāng 。', example_vietnamese = 'Các vận động viên Đài Loan tranh giành chiến thắng trong các giải đấu quốc tế, mang lại vinh quang cho đất nước.' WHERE id = 'a63f5b50-1771-4b7f-af88-2a14b18f377f';
UPDATE public.dictionary_words SET example_hanzi = '這次創業雖然失敗了，但他從中學到了寶貴的經驗。', example_pinyin = 'zhè cì chuàng yè suī rán shī bài le ， dàn tā cóng zhōng xué dào le bǎo guì de jīng yàn 。', example_vietnamese = 'Lần khởi nghiệp này tuy thất bại, nhưng anh ấy đã học được kinh nghiệm quý giá từ đó.' WHERE id = 'a856c4a4-23fe-4d36-b13c-f0ba83ba0755';
UPDATE public.dictionary_words SET example_hanzi = '他失掉了這場棒球比賽的關鍵分數，讓球隊輸了。', example_pinyin = 'tā shī diào le zhè chǎng bàng qiú bǐ sài de guān jiàn fēn shù ， ràng qiú duì shū le 。', example_vietnamese = 'Anh ấy đã đánh mất điểm số quan trọng trong trận bóng chày này, khiến đội thua cuộc.' WHERE id = '78ea3a8c-2038-408d-b137-2b360cd5e316';
UPDATE public.dictionary_words SET example_hanzi = '考試前一晚，許多學生會因為壓力大而失眠。', example_pinyin = 'kǎo shì qián yì wǎn ， xū duō xué shēng huì yīn wéi yā lì dà ér shī mián 。', example_vietnamese = 'Đêm trước kỳ thi, nhiều học sinh sẽ bị mất ngủ vì áp lực lớn.' WHERE id = '5423cf3e-3963-4666-a147-348012d88dc9';
UPDATE public.dictionary_words SET example_hanzi = '颱風天原本計畫去墾丁玩，結果行程取消讓我有點失望。', example_pinyin = 'tái fēng tiān yuán běn jì huà qù kěn dīng wán ， jié guǒ xíng chéng qǔ xiāo ràng wǒ yǒu diǎn shī wàng 。', example_vietnamese = 'Ngày bão, ban đầu tôi định đi chơi Kenting, nhưng kết quả là lịch trình bị hủy khiến tôi hơi thất vọng.' WHERE id = '9eb241cc-faab-45b3-a02a-2adcf2f71278';
UPDATE public.dictionary_words SET example_hanzi = '他的朋友最近失業了。', example_pinyin = 'tā de péng yǒu zuì jìn shī yè le 。', example_vietnamese = 'Bạn của anh ấy gần đây bị thất nghiệp rồi.' WHERE id = '821d10bd-424e-471e-9d03-02d5e4449389';
UPDATE public.dictionary_words SET example_hanzi = '小學的時候，老師常教我們朗讀臺灣本土詩人的詩。', example_pinyin = 'xiǎo xué de shí hòu ， lǎo shī cháng jiào wǒ men lǎng dú tái wān běn tǔ shī rén de shī 。', example_vietnamese = 'Khi học tiểu học, thầy cô thường dạy chúng tôi đọc thơ của các nhà thơ bản địa Đài Loan.' WHERE id = 'd3d9c2b1-6e8f-490c-b05d-e5c59468fd17';
UPDATE public.dictionary_words SET example_hanzi = '臺灣有許多優秀的詩人，他們的創作反映了這片土地的人文風景。', example_pinyin = 'tái wān yǒu xū duō yōu xiù de shī rén ， tā men de chuàng zuò fǎn yìng le zhè piàn tǔ dì de rén wén fēng jǐng 。', example_vietnamese = 'Đài Loan có nhiều nhà thơ xuất sắc, tác phẩm của họ phản ánh phong cảnh văn hóa của mảnh đất này.' WHERE id = '80a2a3f3-883c-4003-b303-5b48bbba39ec';
UPDATE public.dictionary_words SET example_hanzi = '很多學徒會跟著糕餅店的師父學習傳統手藝。', example_pinyin = 'hěn duō xué tú huì gēn zhù gāo bǐng diàn de shī fù xué xí chuán tǒng shǒu yì 。', example_vietnamese = 'Nhiều người học nghề sẽ theo sư phụ của tiệm bánh kẹo để học các nghề thủ công truyền thống.' WHERE id = '0c0fe5d2-e484-402d-83b6-0cc0d6ae47d2';
UPDATE public.dictionary_words SET example_hanzi = '公車司機師傅很熟練地開著車，穿梭在臺北的巷弄間。', example_pinyin = 'gōng chē sī jī shī fù hěn shú liàn dì kāi zhù chē ， chuān suō zài tái běi de xiàng nòng jiàn 。', example_vietnamese = 'Bác tài xế xe buýt lái xe rất thuần thục, luồn lách qua các con hẻm ở Đài Bắc.' WHERE id = '3df4d5fd-6a58-41d6-95c5-7208b6ccad50';
UPDATE public.dictionary_words SET example_hanzi = '以前在眷村裡，大家都對師母非常尊敬，把她當作長輩。', example_pinyin = 'yǐ qián zài juàn cūn lǐ ， dà jiā dōu duì shī mǔ fēi cháng zūn jìng ， bǎ tā dāng zuò cháng bèi 。', example_vietnamese = 'Ngày xưa ở làng quân nhân, mọi người đều rất kính trọng sư mẫu, coi bà như bậc trưởng bối.' WHERE id = '1c2c6a39-5645-483c-badc-9f3ed4361d61';
UPDATE public.dictionary_words SET example_hanzi = '捷運站附近正在施工，交通會比較壅塞。', example_pinyin = 'jié yùn zhàn fù jìn zhèng zài shī gōng ， jiāo tōng huì bǐ jiào yōng sè 。', example_vietnamese = 'Gần ga MRT đang thi công, giao thông sẽ khá ùn tắc.' WHERE id = '7675b3c2-31ac-48ff-9f88-a2e01451703c';
UPDATE public.dictionary_words SET example_hanzi = '臺灣夏天時常有午後雷陣雨，出門要記得帶傘。', example_pinyin = 'tái wān xià tiān shí cháng yǒu wǔ hòu léi zhèn yǔ ， chū mén yào jì dé dài sǎn 。', example_vietnamese = 'Mùa hè ở Đài Loan thường có những cơn mưa dông buổi chiều, ra ngoài nhớ mang theo ô.' WHERE id = 'e1319111-426d-4c71-b2f4-21d22c1a239f';
UPDATE public.dictionary_words SET example_hanzi = '現在是品嚐臺灣芒果的最佳時機，香甜又多汁。', example_pinyin = 'xiàn zài shì pǐn cháng tái wān máng guǒ de zuì jiā shí jī ， xiāng tián yòu duō zhī 。', example_vietnamese = 'Bây giờ là thời điểm tốt nhất để thưởng thức xoài Đài Loan, vừa ngọt vừa mọng nước.' WHERE id = '323f3653-aec1-46cd-b5b1-e24620bc526b';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的梅雨時期通常在五月到六月，會持續一段時間。', example_pinyin = 'tái wān de méi yǔ shí qī tōng cháng zài wǔ yuè dào liù yuè ， huì chí xù yí duàn shí jiàn 。', example_vietnamese = 'Mùa mưa mận ở Đài Loan thường kéo dài từ tháng 5 đến tháng 6.' WHERE id = 'e68d7657-503a-479e-9390-35062161f92b';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的便利商店時時都提供熱食和飲料，滿足顧客需求。', example_pinyin = 'tái wān de biàn lì shāng diàn shí shí dōu tí gōng rè shí hé yǐn liào ， mǎn zú gù kè xū qiú 。', example_vietnamese = 'Các cửa hàng tiện lợi ở Đài Loan luôn cung cấp đồ ăn nóng và đồ uống, đáp ứng nhu cầu của khách hàng.' WHERE id = 'c797d807-df10-4d10-af35-66baacb01d72';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的便利商店販售各式各樣的食品，從便當到零食應有盡有。', example_pinyin = 'tái wān de biàn lì shāng diàn fàn shòu gè shì gè yàng de shí pǐn ， cóng biàn dāng dào líng shí yīng yǒu jìn yǒu 。', example_vietnamese = 'Các cửa hàng tiện lợi ở Đài Loan bán đủ loại thực phẩm, từ cơm hộp đến đồ ăn vặt.' WHERE id = '966ec1dd-e82c-45bd-b6f4-a6694fbf97e6';
UPDATE public.dictionary_words SET example_hanzi = '這是一本很實用的書。', example_pinyin = 'zhè shì yì běn hěn shí yòng de shū 。', example_vietnamese = 'Đây là một cuốn sách rất thiết thực.' WHERE id = '46db1bf5-ca95-4642-b3f6-4c1905f490dc';
