UPDATE public.dictionary_words SET example_hanzi = '臺北市政府將實施新的垃圾費隨袋徵收政策。', example_pinyin = 'tái běi shì zhèng fǔ jiāng shí shī xīn de lā jī fèi suí dài zhǐ shōu zhèng cè 。', example_vietnamese = 'Chính quyền thành phố Đài Bắc sẽ thực hiện chính sách thu phí rác thải mới theo túi.' WHERE id = 'd983283b-a821-48cd-b1b3-dfbb92de6f21';
