UPDATE public.dictionary_words SET example_hanzi = '在17世紀，荷蘭人曾來到臺灣進行貿易和殖民。', example_pinyin = 'zài 1 7 shì jì ， hé lán rén céng lái dào tái wān jìn xíng mào yì hé zhí mín 。', example_vietnamese = 'Vào thế kỷ 17, người Hà Lan từng đến Đài Loan để giao thương và thực dân hóa.' WHERE id = 'f7cd30d9-3878-4cc1-82dd-17ab18e16d2f';
UPDATE public.dictionary_words SET example_hanzi = '臺北市立動物園是許多家庭週末出遊的好去處。', example_pinyin = 'tái běi shì lì dòng wù yuán shì xū duō jiā tíng zhōu mò chū yóu de hǎo qù chǔ 。', example_vietnamese = 'Sở thú thành phố Đài Bắc là một địa điểm lý tưởng để nhiều gia đình đi chơi vào cuối tuần.' WHERE id = '2111e7c0-6e7e-4f56-b53d-bd3c29030852';
UPDATE public.dictionary_words SET example_hanzi = '臺北市民可以透過「1999市民服務專線」反映市政問題。', example_pinyin = 'tái běi shì mín kě yǐ tòu guò 「 1 9 9 9 shì mín fú wù zhuān xiàn 」 fǎn yìng shì zhèng wèn tí 。', example_vietnamese = 'Công dân Đài Bắc có thể phản ánh các vấn đề đô thị thông qua "Đường dây nóng dịch vụ công dân 1999".' WHERE id = 'fa24da1c-ca21-48f9-b824-7660a9a01850';
UPDATE public.dictionary_words SET example_hanzi = '我們住在市區。', example_pinyin = 'wǒ men zhù zài shì qū 。', example_vietnamese = 'Chúng tôi sống ở khu vực nội thành.' WHERE id = 'c8fca69d-721d-4d95-865a-c7e15176d1d2';
UPDATE public.dictionary_words SET example_hanzi = '臺灣人很重視家庭，視親情為生命中最寶貴的資產。', example_pinyin = 'tái wān rén hěn zhòng shì jiā tíng ， shì qīn qíng wéi shēng mìng zhòng zuì bǎo guì de zī chǎn 。', example_vietnamese = 'Người Đài Loan rất coi trọng gia đình, xem tình thân là tài sản quý giá nhất trong đời.' WHERE id = 'e40ef4b4-e315-4907-a4c6-3bd030800fe8';
UPDATE public.dictionary_words SET example_hanzi = '站在象山頂可以俯瞰臺北101，視野很好。', example_pinyin = 'zhàn zài xiàng shān dǐng kě yǐ fǔ kàn tái běi 1 0 1 ， shì yě hěn hǎo 。', example_vietnamese = 'Đứng trên đỉnh núi Tượng Sơn có thể nhìn toàn cảnh Taipei 101, tầm nhìn rất đẹp.' WHERE id = '5e09f604-e69c-4047-b4f3-f553743eee19';
UPDATE public.dictionary_words SET example_hanzi = '臺灣的夏天很熱，記得穿著適當的輕便衣物。', example_pinyin = 'tái wān de xià tiān hěn rè ， jì dé chuān zhù shì dāng de qīng biàn yī wù 。', example_vietnamese = 'Mùa hè ở Đài Loan rất nóng, nhớ mặc trang phục phù hợp, nhẹ nhàng.' WHERE id = 'c0fef805-ca64-4112-813e-afbd361db5de';
UPDATE public.dictionary_words SET example_hanzi = '這件衣服很適合你。', example_pinyin = 'zhè jiàn yī fu hěn shì hé nǐ 。', example_vietnamese = 'Bộ quần áo này rất hợp với bạn.' WHERE id = '642f5a15-a1de-4209-84ad-6bd9e67bf9c5';
