UPDATE public.dictionary_words SET example_hanzi = '在面對網路上的虛假資訊時，更要學會獨立思考，分辨是非。', example_pinyin = 'zài miàn duì wǎng lù shang de xū jiǎ zī xùn shí ， gèng yào xué huì dú lì sī kǎo ， fēn biàn shì fēi 。', example_vietnamese = 'Khi đối mặt với thông tin giả mạo trên mạng, càng phải học cách suy nghĩ độc lập, phân biệt đúng sai.' WHERE id = '73f7aa9c-e12a-4159-97ea-6e05754bf0e9';
UPDATE public.dictionary_words SET example_hanzi = '我們需要確認這班高鐵是否會準時抵達臺中站。', example_pinyin = 'wǒ men xū yào què rèn zhè bān gāo tiě shì fǒu huì zhǔn shí dǐ dá tái zhōng zhàn 。', example_vietnamese = 'Chúng tôi cần xác nhận xem chuyến tàu cao tốc này có đến ga Đài Trung đúng giờ hay không.' WHERE id = 'f2496c24-9043-4da2-901c-e7ac9386f349';
UPDATE public.dictionary_words SET example_hanzi = '這次在臺北小巨蛋舉辦的演唱會是一個備受矚目的音樂事件。', example_pinyin = 'zhè cì zài tái běi xiǎo jù dàn jǔ bàn de yǎn chàng huì shì yí gè bèi shòu zhǔ mù dì yīn lè shì jiàn 。', example_vietnamese = 'Buổi hòa nhạc lần này được tổ chức tại Nhà thi đấu Đài Bắc là một sự kiện âm nhạc được mong chờ.' WHERE id = 'c89d76bf-0e58-4b2c-9bb8-1a8e73f54f3c';
UPDATE public.dictionary_words SET example_hanzi = '大家以為臭豆腐聞起來很臭，但事實上吃起來非常香。', example_pinyin = 'dà jiā yǐ wéi chòu dòu fu wén qǐ lái hěn chòu ， dàn shì shí shàng chī qǐ lái fēi cháng xiāng 。', example_vietnamese = 'Mọi người đều nghĩ đậu phụ thối có mùi rất hôi, nhưng thực ra ăn rất thơm ngon.' WHERE id = '00b9b1bf-cb23-4096-8c8f-66b758d0781f';
UPDATE public.dictionary_words SET example_hanzi = '我喜歡觀察周遭的事物。', example_pinyin = 'wǒ xǐ huān guān chá zhōu zāo de shì wù 。', example_vietnamese = 'Tôi thích quan sát những sự vật xung quanh.' WHERE id = 'aa9ca23f-c2cf-4556-bd06-458e34761462';
