UPDATE public.dictionary_words SET example_hanzi = '在臺灣傳統市場中，有時候地方派系的勢力不容小覷。', example_pinyin = 'zài tái wān chuán tǒng shì chǎng zhōng ， yǒu shí hòu dì fāng pài xì de shì lì bù róng xiǎo qù 。', example_vietnamese = 'Trong các chợ truyền thống Đài Loan, đôi khi thế lực của các phe phái địa phương không thể bị xem nhẹ.' WHERE id = 'f42a1c7c-5f61-4d0f-a97b-93c2160fab3d';
